bugRepair.brokenCode:
.featured-card {
  /* محاولة تمديد العنصر عبر عمودين */
  grid-column: 2;
  /* النتيجة: العنصر ينتقل للعمود الثاني ولا يمتد! */
}

.grid-12 {
  display: grid;
  /* المطور كتب 10 أعمدة بالخطأ */
  grid-template-columns: repeat(10, 1fr);
}
.half-col {
  grid-column: span 6;
  /* النتيجة: نصف الشاشة مشوه لأن 6 من 10 ليست 50%! */
}

bugRepair.fixedCode:
.grid-12 {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
}
.half-col {
  grid-column: span 6;
}
